import {money,sum,metrics,validate} from './finance.js';
const $=id=>document.getElementById(id);let data,activeMonth;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const monthLabel=key=>new Date(key+'-15T12:00:00').toLocaleDateString('en-US',{month:'long',year:'numeric'});
function render(){const m=data.months.find(m=>m.key===activeMonth)||data.months.at(-1);activeMonth=m.key;$('month').value=activeMonth;const k=metrics(m);
 $('overview').innerHTML=[['Rent collected',money(k.collected),monthLabel(m.key)],['Scheduled rent',money(k.scheduled),`${m.units.length} units on the rent roll`],['Outstanding balance',money(k.outstanding),k.credits?`${money(k.credits)} in separate credits`:'No credits recorded'],['Units paid up',`${k.settled} / ${m.units.length}`,'Based on recorded balances']].map(x=>`<article class="kpi"><p>${esc(x[0])}</p><strong>${esc(x[1])}</strong><small>${esc(x[2])}</small></article>`).join('');
 const months=data.months.slice(-6),max=Math.max(1,...months.map(m=>Math.max(sum(m.units,'rent'),sum(m.units,'paid'))));
 $('trend').innerHTML=months.map(m=>{const scheduled=sum(m.units,'rent'),paid=sum(m.units,'paid');return `<div class="chart-group"><strong>${money(paid)}</strong><div class="bars" role="img" aria-label="${esc(monthLabel(m.key))}: scheduled ${money(scheduled)}, collected ${money(paid)}"><div class="bar" style="height:${Math.max(0,scheduled)/max*100}%"></div><div class="bar actual" style="height:${Math.max(0,paid)/max*100}%"></div></div><small>${esc(monthLabel(m.key))}</small></div>`}).join('');
 $('collection-rate').textContent=k.rate===null?'—':`${Math.round(k.rate*100)}%`;$('ring').style.background=`conic-gradient(#315c44 ${Math.max(0,Math.min(100,(k.rate||0)*100))}%,#edf0e9 0)`;$('collection-caption').textContent=`${money(k.collected)} collected of ${money(k.scheduled)} scheduled`;
 const query=$('search').value.toLowerCase();$('units').innerHTML=m.units.filter(u=>(u.unit+' '+u.address).toLowerCase().includes(query)).map(u=>`<tr><td><strong>${esc(u.unit)}</strong><small>${esc(u.address)}</small></td><td>${money(u.rent)}</td><td>${money(u.paid)}</td><td>${money(u.balance)}</td><td><span class="pill ${u.balance>0?'due':u.balance<0?'credit':''}">${u.balance>0?'Balance due':u.balance<0?'Credit':'Paid up'}</span></td></tr>`).join('')||'<tr><td colspan="5">No matching units.</td></tr>';
 $('budget').innerHTML=data.budget.map(b=>`<div class="budget-row"><span>${esc(b.label)}</span><strong>${money(b.amount)}</strong></div>`).join('');$('plan-net').textContent=money(sum(data.budget,'amount'));renderExpenses();}
function renderExpenses(){let f=$('expense-filter').value;let rows=data.expenses.filter(r=>f==='all'||(f==='paid'?r.paid>0:r.unpaid>0));$('expenses').innerHTML=rows.map(r=>`<tr><td>${esc(r.date||'Undated')}</td><td>${esc(r.category)}</td><td>${r.paid?money(r.paid):'—'}</td><td>${r.unpaid?money(r.unpaid):'—'}</td><td>${esc(r.source)} ${esc(r.row)}</td></tr>`).join('')||'<tr><td colspan="5">No matching records.</td></tr>';}
async function refresh(){const endpoint=window.DASHBOARD_CONFIG.endpoint;const b=$('refresh');b.disabled=true;try{const response=await fetch(endpoint||'data.json',{cache:'no-store',signal:AbortSignal.timeout(20000)});if(!response.ok)throw Error(`Data request failed (${response.status}).`);const next=validate(await response.json());data=next;const selected=activeMonth;data.months.sort((a,b)=>a.key.localeCompare(b.key));activeMonth=data.months.some(m=>m.key===selected)?selected:data.months.at(-1).key;$('month').innerHTML=data.months.map(m=>`<option value="${esc(m.key)}">${esc(monthLabel(m.key))}</option>`).join('');render();$('sync-status').className=endpoint?'':'warning';$('sync-status').textContent=endpoint?`Live spreadsheet · refreshed ${new Date().toLocaleTimeString('en-US',{timeZone:'America/Chicago',hour:'numeric',minute:'2-digit'})} CT`:`Saved snapshot · ${data.asOf} · Live connection not configured`;}catch(e){$('sync-status').className='warning';$('sync-status').textContent=`Refresh failed. ${data?'Showing the last successfully loaded records. ':''}${e.message}`;}finally{b.disabled=false;}}
$('month').addEventListener('change',e=>{activeMonth=e.target.value;render()});$('search').addEventListener('input',()=>data&&render());$('expense-filter').addEventListener('change',()=>data&&renderExpenses());$('refresh').addEventListener('click',refresh);refresh();setInterval(()=>{if(window.DASHBOARD_CONFIG.endpoint&&!document.hidden)refresh()},window.DASHBOARD_CONFIG.refreshMilliseconds||300000);
